## 附件：scripts/run_engine.cjs

````javascript
#!/usr/bin/env node
'use strict';

// Optional local calculation bridge. This script never calls an LLM or network API.
const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');

const engines = new Set([
  'stability', 'service_only', 'weekly_report', 'sales_funnel', 'attribution',
  'tracking', 'sales_attribution', 'weekly_metrics', 'process_efficiency'
]);
const attributionMethods = new Set([
  'shiftShare', 'standardize', 'compareCells', 'scanCoverage', 'profileIndices',
  'segmentProfiles', 'compareProfileDrift', 'periodTrends'
]);

function fail(code, message, location) {
  const error = new Error(message);
  error.code = code;
  if (location) error.path = location;
  throw error;
}

function isObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function parseArgs(argv) {
  const values = new Set(['--engine', '--method', '--input', '--output', '--engines-root']);
  const flags = new Set(['--describe', '--help']);
  const options = Object.create(null);
  for (let i = 0; i < argv.length; i++) {
    const key = argv[i];
    if ((!values.has(key) && !flags.has(key)) || Object.hasOwn(options, key)) {
      fail('ARGUMENT_ERROR', `未知或重复参数：${key}`);
    }
    if (flags.has(key)) options[key] = true;
    else {
      const value = argv[++i];
      if (!value || value.startsWith('--')) fail('ARGUMENT_ERROR', `${key} 缺少值`);
      options[key] = value;
    }
  }
  return options;
}

function readJSON(file) {
  const raw = fs.readFileSync(file, 'utf8').replace(/^\uFEFF/, '');
  try { return {raw, value: JSON.parse(raw)}; }
  catch (error) { fail('INVALID_JSON', error.message, file); }
}

function insideRoot(root, relative) {
  const file = fs.realpathSync(path.resolve(root, relative));
  const difference = path.relative(root, file);
  if (difference === '..' || difference.startsWith(`..${path.sep}`) || path.isAbsolute(difference)) {
    fail('INVALID_ENGINE_PATH', '引擎文件必须位于所选算法包内', file);
  }
  return file;
}

function emit(value, output) {
  const serialized = JSON.stringify(value, null, 2) + '\n';
  if (output) {
    const target = path.resolve(output);
    fs.writeFileSync(target, serialized, {encoding: 'utf8', flag: 'wx'});
    process.stdout.write(JSON.stringify({output: target}) + '\n');
  } else process.stdout.write(serialized);
}

function main() {
  const args = parseArgs(process.argv.slice(2));
  if (args['--help']) {
    process.stdout.write([
      'node run_engine.cjs --engine ID --input request.json [--output result.json]',
      '  [--method analyze] [--engines-root /path/to/算法引擎合集]',
      'node run_engine.cjs --engine ID --describe [--engines-root DIR]',
      'request.json: {"input": {...}, "options": {...}}',
      'Root: --engines-root, then OPS_SKILL_ENGINES_DIR, then sibling 算法引擎合集.',
